 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    # The pattern is three adjacent colored anchors across the first row.
    starts = [c for c in range(w - 2)
              if all(out[0][j] != 0 for j in range(c, c + 3))]
    if not starts:
        return out
    start = starts[0]
    anchors = [(start + i, out[0][start + i]) for i in range(3)]
    for ac, color in anchors:
        markers = [(r, c) for r in range(h) for c in range(w)
                   if out[r][c] == color and (r, c) != (0, ac)]
        if markers:
            mr, mc = markers[0]
        else:
            mr, mc = h - 1, ac
        for r in range(0, mr + 1):
            out[r][ac] = color
        for c in range(min(ac, mc), max(ac, mc) + 1):
            out[mr][c] = color
    return out
